const body = $json.body ?? $json;
const clean = (value) => String(value ?? '').trim();
return {
  source: clean(body.source || 'webhook').toLowerCase(),
  first_name: clean(body.first_name),
  last_name: clean(body.last_name),
  company: clean(body.company),
  email: clean(body.email).toLowerCase(),
  phone: clean(body.phone),
  website: clean(body.website),
  industry: clean(body.industry),
  country: clean(body.country),
  service_interest: clean(body.service_interest),
  message: clean(body.message),
  raw_payload: body
};

const errors = [];
if (!$json.email) errors.push('email is required');
if ($json.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test($json.email)) errors.push('email is invalid');
if (!$json.message) errors.push('message is required');
if ($json.message && $json.message.length > 5000) errors.push('message exceeds 5000 characters');
return { ...$json, valid: errors.length === 0, validation_errors: errors };

