const score = Math.max(0, Math.min(100, Number(query.score)));
const confidence = Math.max(0, Math.min(1, Number(query.confidence)));
const hot = Number(query.hot_threshold);
const warm = Number(query.warm_threshold);
const minimum = Number(query.minimum_confidence);
const temperature = score >= hot ? 'hot' : score >= warm ? 'warm' : 'cold';
let next_action = ['send_followup','convert_lead','manual_review','no_action'].includes(query.requested_action)
  ? query.requested_action
  : 'manual_review';
if (confidence < minimum) next_action = 'manual_review';
if (next_action === 'convert_lead' && (temperature !== 'hot' || confidence < 0.85)) next_action = 'manual_review';
if (temperature === 'cold' && next_action === 'send_followup') next_action = 'no_action';
return JSON.stringify({
  score: Math.round(score),
  temperature,
  confidence,
  next_action,
  requires_approval: ['send_followup','convert_lead'].includes(next_action)
});

