const lead = $('Upsert Lead').first().json;
const config = $('Workflow Configuration').first().json;
let decision = $json.output ?? $json;
let parseError = '';
if (typeof decision === 'string') {
  try { decision = JSON.parse(decision); } catch (error) { parseError = error.message; decision = {}; }
}
const score = Number(decision.score);
const confidence = Number(decision.confidence);
const allowedActions = ['send_followup','convert_lead','manual_review','no_action'];
let nextAction = allowedActions.includes(decision.next_action) ? decision.next_action : 'manual_review';
const expectedTemperature = Number.isFinite(score)
  ? (score >= Number(config.hot_threshold) ? 'hot' : score >= Number(config.warm_threshold) ? 'warm' : 'cold')
  : 'cold';
if (!Number.isFinite(confidence) || confidence < Number(config.minimum_confidence)) nextAction = 'manual_review';
if (nextAction === 'convert_lead' && (expectedTemperature !== 'hot' || confidence < 0.85)) nextAction = 'manual_review';
if (expectedTemperature === 'cold' && nextAction === 'send_followup') nextAction = 'no_action';
const requiredFields = ['recommended_service','reasoning_summary','email_subject','email_body'];
const missing = requiredFields.filter((field) => typeof decision[field] !== 'string');
const valid = !parseError && Number.isFinite(score) && score >= 0 && score <= 100 && Number.isFinite(confidence) && missing.length === 0;
return {
  ...lead,
  ...decision,
  score: Number.isFinite(score) ? Math.round(score) : null,
  temperature: expectedTemperature,
  confidence: Number.isFinite(confidence) ? confidence : 0,
  next_action: valid ? nextAction : 'manual_review',
  requires_approval: valid && ['send_followup','convert_lead'].includes(nextAction),
  valid,
  agent_error: parseError || (missing.length ? 'Missing fields: ' + missing.join(', ') : ($json.error?.message ?? ''))
};

